mapper.select:
SELECT id,currency,input_price,cached_input_price,output_price
FROM ai_model_price_version
WHERE tenant_id=#{tenantId} AND provider=#{provider} AND model_name=#{modelName}
  AND enabled=1 AND effective_from<=#{at}
ORDER BY effective_from DESC,id DESC LIMIT 1

mapper.update:
UPDATE ai_model_call_log SET model_name=#{modelName},response_id=#{responseId},input_tokens=#{inputTokens},cached_input_tokens=#{cachedInputTokens},output_tokens=#{outputTokens},
usage_status=#{usageStatus},price_version_id=#{priceVersionId},currency=#{currency},input_price=#{inputPrice},cached_input_price=#{cachedInputPrice},output_price=#{outputPrice},estimated_cost=#{estimatedCost},cost_status=#{costStatus}
WHERE call_id=#{callId} AND tenant_id=#{tenantId} AND usage_status='UNKNOWN'

UPDATE ai_model_call_log SET outcome=#{outcome},error_category=#{errorCategory},finished_at=#{finishedAt},duration_ms=#{durationMs},ttft_ms=#{ttftMs},model_name=#{modelName},response_id=#{responseId},
input_tokens=#{inputTokens},cached_input_tokens=#{cachedInputTokens},output_tokens=#{outputTokens},usage_status=#{usageStatus},price_version_id=#{priceVersionId},currency=#{currency},input_price=#{inputPrice},cached_input_price=#{cachedInputPrice},output_price=#{outputPrice},estimated_cost=#{estimatedCost},cost_status=#{costStatus}
WHERE call_id=#{callId} AND tenant_id=#{tenantId} AND outcome='IN_PROGRESS'
